import{_ as o,c as a,o as t,a0 as d}from"./chunks/framework.C1J0Vcxi.js";const _=JSON.parse('{"title":"第二十六周：AMP IPC 死锁修复与 ov-channels 泛型化重构","description":"","frontmatter":{"title":"第二十六周：AMP IPC 死锁修复与 ov-channels 泛型化重构","date":"2026-06-03"},"headers":[],"relativePath":"周报-Oveln/2026-06-03-周报二十六.md","filePath":"周报-Oveln/2026-06-03-周报二十六.md"}'),r={name:"周报-Oveln/2026-06-03-周报二十六.md"};function c(l,e,i,n,s,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="第二十六周工作总结" tabindex="-1">第二十六周工作总结 <a class="header-anchor" href="#第二十六周工作总结" aria-label="Permalink to &quot;第二十六周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本周围绕 rt-async-amp 项目的 AMP IPC 通信，完成了三个阶段的工作：</p><ol><li><strong>定位并修复 IPC 死锁</strong>：根因是 <code>PollSet</code> 内部 <code>spin::Mutex</code> 不关中断，IPI handler 与 register 在同一 hart 上死锁</li><li><strong>重构 StarryOS 侧 await 机制</strong>：彻底移除中间计数器，改为直接读取 ring buffer 状态 + Waker 唤醒</li><li><strong>ov-channels 库泛型化重构并发布 v0.2.0</strong>：<code>SharedMemory&lt;const N&gt;</code> 泛型化，新增 <code>flags</code> feature gate</li></ol><h2 id="_1-amp-ipc-死锁排查与修复" tabindex="-1">1. AMP IPC 死锁排查与修复 <a class="header-anchor" href="#_1-amp-ipc-死锁排查与修复" aria-label="Permalink to &quot;1. AMP IPC 死锁排查与修复&quot;">​</a></h2><h3 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h3><p><code>user-test-sched</code> 三明治计时测试中，客户端 <code>await_ipi</code> 永久阻塞。死锁只在完整 RPC 流程（DELAY + ECHO 连续调用）中出现，单步调用正常。</p><h3 id="根因分析" tabindex="-1">根因分析 <a class="header-anchor" href="#根因分析" aria-label="Permalink to &quot;根因分析&quot;">​</a></h3><p><code>PollSet</code> 内部使用 <code>spin::Mutex</code>（裸自旋锁，不关中断）保护 waker 队列。当 Task 在 hart 0 上调用 <code>register(waker)</code> 持有锁时，同一 hart 的 IPI 中断到达，<code>ipi_irq_handler</code> 尝试调用 <code>wake()</code> 获取同一把锁——中断 handler 等待被中断的代码释放锁，锁永远不会被释放。</p><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><strong>服务端</strong>：<code>send_notify_ipi()</code> 封装 IPI 发送，每个 Notify 响应立即回 IPI</li><li><strong>Linux 侧</strong>：<code>SpinNoIrq&lt;Option&lt;Waker&gt;&gt;</code> 替换 <code>PollSet</code>（关中断保护 waker 注册）；移除 <code>IPC_PENDING</code>，改为直接读 CH1 ring buffer 判断消息可用性</li><li>IPI handler 仅 wake 已注册的 Waker，spurious wakeup 安全因为 ring buffer 是权威状态</li></ul><p>详细排查过程记录在 <a href="./../技术报告/2026-06-03-AMP死锁排查.html">AMP 死锁排查技术报告</a>。</p><h3 id="相关文件变更" tabindex="-1">相关文件变更 <a class="header-anchor" href="#相关文件变更" aria-label="Permalink to &quot;相关文件变更&quot;">​</a></h3><ul><li><code>apps/rt-async-app/src/intercom.rs</code>：IPI 策略重构、弹性自旋窗口扩大（1000→100000）、新增日志</li><li><code>StarryOS/kernel/src/pseudofs/dev/rt_shm.rs</code>：移除 <code>IPC_PENDING</code>/<code>PollSet</code>，改用 <code>ch1_has_pending()</code> + <code>IPC_WAKER</code></li><li><code>apps/rt-async-app/src/ipc_wait.rs</code>：ISR 唤醒日志</li></ul><h2 id="_2-starryos-rt-shm-设备重构" tabindex="-1">2. StarryOS rt_shm 设备重构 <a class="header-anchor" href="#_2-starryos-rt-shm-设备重构" aria-label="Permalink to &quot;2. StarryOS rt_shm 设备重构&quot;">​</a></h2><h3 id="移除的机制" tabindex="-1">移除的机制 <a class="header-anchor" href="#移除的机制" aria-label="Permalink to &quot;移除的机制&quot;">​</a></h3><ul><li><code>IPC_PENDING: AtomicBool</code> — 中间标志，与实际消息数不一致时导致死锁</li><li><code>IPC_POLLSET: PollSet</code> — spin::Mutex 不关中断，同 hart 死锁</li><li>IPI handler 中手动清除 MSIP/SIP 的代码</li></ul><h3 id="新机制" tabindex="-1">新机制 <a class="header-anchor" href="#新机制" aria-label="Permalink to &quot;新机制&quot;">​</a></h3><ul><li><code>ch1_has_pending()</code>：直接读 CH1 ring buffer 的 <code>read</code>/<code>write</code> 原子变量（offset 从 <code>amp.toml</code> 生成）</li><li><code>IPC_WAKER: SpinNoIrq&lt;Option&lt;Waker&gt;&gt;</code>：IRQ-safe 的 waker 存储</li><li><code>AWAIT</code> ioctl：先检查 <code>ch1_has_pending()</code> → 加锁注册 waker → 二次检查 → Pending/Ready</li><li><code>ipi_irq_handler()</code>：仅 <code>IPC_WAKER.lock().take()</code> + <code>waker.wake()</code></li><li><code>CLR_PENDING</code> ioctl 变为 no-op（保留 ABI 兼容）</li></ul><h2 id="_3-ov-channels-v0-2-0-泛型化重构" tabindex="-1">3. ov-channels v0.2.0 泛型化重构 <a class="header-anchor" href="#_3-ov-channels-v0-2-0-泛型化重构" aria-label="Permalink to &quot;3. ov-channels v0.2.0 泛型化重构&quot;">​</a></h2><h3 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to &quot;动机&quot;">​</a></h3><p><code>SharedMemory</code> 硬编码 <code>MAX_CHANNELS = 4</code>，外部无法自定义通道数量。作为通用库应允许调用方在编译时指定。</p><h3 id="核心改动" tabindex="-1">核心改动 <a class="header-anchor" href="#核心改动" aria-label="Permalink to &quot;核心改动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变更</th><th>说明</th></tr></thead><tbody><tr><td><code>SharedMemory&lt;const N: usize = 2&gt;</code></td><td>const generics 泛型化，默认 2 通道</td></tr><tr><td>新增 <code>flags</code> feature</td><td>门控 <code>busy: AtomicBool</code> 及 <code>set_busy</code>/<code>clear_busy</code>/<code>is_busy</code> API</td></tr><tr><td>移除 <code>MAX_CHANNELS</code></td><td>不再硬编码通道数上限</td></tr><tr><td><code>ChannelId</code> 简化</td><td>去掉 <code>is_valid()</code> 和范围检查，校验下沉到 <code>SharedMemory&lt;N&gt;</code></td></tr><tr><td><code>sender()</code>/<code>receiver()</code></td><td>用 <code>(id.get() as usize) &lt; N</code> 动态校验</td></tr><tr><td><code>recv_from_interrupt&lt;N&gt;</code> / <code>has_pending_interrupt&lt;N&gt;</code></td><td>泛型化</td></tr><tr><td>新增 <code>channel_count()</code></td><td>返回 N</td></tr></tbody></table><h3 id="依赖更新" tabindex="-1">依赖更新 <a class="header-anchor" href="#依赖更新" aria-label="Permalink to &quot;依赖更新&quot;">​</a></h3><ul><li>发布到 crates.io（<code>ov-channels = &quot;0.2.0&quot;</code>）</li><li><code>rt-async-amp</code> workspace 改为 crates.io 依赖 + <code>flags</code> feature</li><li><code>ov-rpc</code> server/client 使用 <code>SharedMemory&lt;3&gt;</code>（CH0 请求、CH1 响应、CH2 急停）</li><li><code>StarryOS</code> 移除未使用的 <code>ov-channal</code> git 依赖</li></ul><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h3><ul><li>ov-channels：33 个测试全部通过（含 <code>std</code> + <code>flags</code> feature 组合）</li><li>ov-rpc：35 个测试全部通过</li></ul>',28)])])}const p=o(r,[["render",c]]);export{_ as __pageData,p as default};
